// EvalSister：绑定到整个“人物关系”Object，替换代码后对人物类重新计算。
// 同妈妈/孕母的相邻人物使用姐姐/妹妹，同爸爸/精母使用种姐/种妹；母系优先。
function transform(self, input) {
  if (input.type !== 'Object' || input.schema().key !== '人物关系') {
    throw new Error('请把此脚本绑定到整个人物关系属性。');
  }

  const people = world.get_class(self.classId);
  const kinds = world.get_class('关系');
  const persons = people.instances();
  const personByName = new Map(persons.map(person => [person.name, person]));
  const kindByName = new Map(kinds.instances().map(kind => [kind.name, kind]));
  for (const name of ['姐姐', '妹妹', '种姐', '种妹']) {
    if (!kindByName.has(name)) throw new Error(`关系类缺少“${name}”实例。`);
  }

  const one = (items, predicate, label) => {
    const matches = items.filter(predicate);
    if (matches.length !== 1) throw new Error(`人物关系 Schema 中无法唯一定位${label}。`);
    return matches[0];
  };
  const personSchema = one(input.schema().children || [],
    schema => schema.repeatable && schema.keyType === 'Class' && schema.classId === people.id && schema.valueType === 'Object', '人物项');
  const relationSchema = one(personSchema.children || [],
    schema => schema.key === '关系' && schema.valueType === 'Object', '关系对象');
  const kindSchema = one(relationSchema.children || [],
    schema => schema.repeatable && schema.keyType === 'Class' && schema.classId === kinds.id && schema.valueType === 'Null', '关系项');
  const storySchema = one(personSchema.children || [],
    schema => schema.key === '人物关系小故事' && schema.valueType === 'Object', '人物关系小故事');

  const linkedName = raw => {
    const text = String(raw || '').trim();
    const match = text.match(/^\[[^\]]*\]\([^#)]+#([^)]*)\)/);
    if (!match) return text;
    try { return decodeURIComponent(match[1]); } catch { return ''; }
  };
  const classLink = (file, name) => `[${name}](${file}#${encodeURIComponent(name)})`;
  // 兼容现有数据中的 YYYY0000 / YYYYMM00；00000000 和空值视为未知。
  const birthdayRange = person => {
    let raw;
    try { raw = String(person.get_member('生日').value() || '').trim(); } catch { return null; }
    if (!/^\d{8}$/.test(raw) || raw === '00000000') return null;
    const year = Number(raw.slice(0, 4));
    const month = Number(raw.slice(4, 6));
    const day = Number(raw.slice(6, 8));
    if (!year || month > 12 || day > 31 || (month === 0 && day !== 0)) return null;
    const valid = (m, d) => {
      const date = new Date(0);
      date.setUTCFullYear(year, m - 1, d);
      return date.getUTCFullYear() === year && date.getUTCMonth() === m - 1 && date.getUTCDate() === d;
    };
    if (month && day && !valid(month, day)) return null;
    const first = year * 10000 + (month || 1) * 100 + (day || 1);
    const lastDay = month ? new Date(Date.UTC(year, month, 0)).getUTCDate() : 31;
    const last = year * 10000 + (month || 12) * 100 + (day || lastDay);
    return {first, last};
  };

  // 妈妈/孕母共用一组，爸爸/精母共用一组；按被引用人物身份分组。
  const maternal = new Map(), paternal = new Map();
  const maternalParents = new Map();
  for (const person of persons) {
    let rows;
    try { rows = person.get_member('人物关系').members(); } catch { continue; }
    for (const row of rows) {
      const parent = personByName.get(linkedName(row.name));
      if (!parent || parent.id === person.id) continue;
      let labels;
      try { labels = row.get_member('关系').members().map(label => linkedName(label.name)); }
      catch { continue; }
      const isMaternal = labels.some(name => name === '妈妈' || name === '孕母');
      const isPaternal = labels.some(name => name === '爸爸' || name === '精母');
      for (const groups of [isMaternal && maternal, isPaternal && paternal]) {
        if (!groups) continue;
        if (!groups.has(parent.id)) groups.set(parent.id, new Map());
        groups.get(parent.id).set(person.id, person);
      }
      if (isMaternal) {
        if (!maternalParents.has(person.id)) maternalParents.set(person.id, new Set());
        maternalParents.get(person.id).add(parent.id);
      }
    }
  }

  const wanted = new Map();
  const shareMaternalParent = (a, b) => {
    const parents = maternalParents.get(a);
    return parents && [...parents].some(id => maternalParents.get(b)?.has(id));
  };
  const collect = (groups, elderKind, youngerKind, paternalGroup) => {
    for (const children of groups.values()) {
      const ordered = [...children.values()].map(person => ({person, date:birthdayRange(person)}))
        .filter(item => item.date)
        .sort((a, b) => a.date.first - b.date.first || a.date.last - b.date.last || a.person.id.localeCompare(b.person.id));
      for (let i = 0; i + 1 < ordered.length; i++) {
        const older = ordered[i], younger = ordered[i + 1];
        if (older.date.last >= younger.date.first) continue; // 无法确定长幼时跳过。
        // 即使两人在母系分组中并不相邻，同母也不生成种姐/种妹。
        if (paternalGroup && shareMaternalParent(older.person.id, younger.person.id)) continue;
        if (self.id === older.person.id) wanted.set(younger.person.id, {person:younger.person, kind:youngerKind});
        if (self.id === younger.person.id) wanted.set(older.person.id, {person:older.person, kind:elderKind});
      }
    }
  };
  collect(maternal, '姐姐', '妹妹', false);
  collect(paternal, '种姐', '种妹', true);

  // 按当前实时成员查重；不覆盖已有关系和小故事。
  const existing = new Map();
  for (const row of self.get_member('人物关系').members()) {
    const target = personByName.get(linkedName(row.name));
    if (!target) continue;
    if (!existing.has(target.id)) existing.set(target.id, []);
    existing.get(target.id).push(row);
  }
  for (const {person, kind} of wanted.values()) {
    const rows = existing.get(person.id) || [];
    if (rows.some(row => {
      try { return row.get_member('关系').members().some(label => linkedName(label.name) === kind); }
      catch { return false; }
    })) continue;
    const key = classLink('关系类型.md', kindByName.get(kind).name);
    if (rows.length) {
      rows[0].get_member('关系').add(kindSchema.id, values.null(), key);
    } else {
      input.add(personSchema.id, values.object([
        {schemaId:relationSchema.id, key:relationSchema.key, value:values.object([
          {schemaId:kindSchema.id, key, value:values.null()}
        ])},
        {schemaId:storySchema.id, key:storySchema.key, value:values.object([])}
      ]), classLink('人物列表.md', person.name));
    }
  }
}
